        [["Review by others", "Presented to the Royal Geographical Society {{wiki-nimrod}}", "Share the plan with someone experienced"], ["Preparation time", "About six months {{wiki-nimrod}}", "Start weeks ahead, not the night before"], ["Local knowledge", "Whaling captains {{shack-south}}", "Ask the landowner, warden or local walkers"], ["Margins", "Depots for the return {{wiki-nimrod}}", "Spare food, a spare layer, time before dark"], ["Roles", "Clear lines of leadership {{shack-south}}", "Navigator, cook and time-keeper"], ["Review", "The record in South", "A written review within a day"]],
